#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int node;
    int state;
} Frame;

static int cmp_int(const void *a, const void *b) {
    int ia = *(const int *)a;
    int ib = *(const int *)b;
    return (ia > ib) - (ia < ib);
}

int main() {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int *edges_u = (int *)malloc(M * sizeof(int));
    int *edges_v = (int *)malloc(M * sizeof(int));
    int *deg = (int *)calloc(N + 1, sizeof(int));

    for (int i = 0; i < M; i++) {
        scanf("%d %d", &edges_u[i], &edges_v[i]);
        deg[edges_u[i]]++;
        deg[edges_v[i]]++;
    }

    int *offset = (int *)malloc((N + 2) * sizeof(int));
    offset[1] = 0;
    for (int i = 1; i <= N; i++) {
        offset[i + 1] = offset[i] + deg[i];
    }

    int *adj = (int *)malloc(2 * M * sizeof(int));
    int *cur_pos = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) {
        cur_pos[i] = offset[i];
    }

    for (int i = 0; i < M; i++) {
        int u = edges_u[i];
        int v = edges_v[i];
        adj[cur_pos[u]++] = v;
        adj[cur_pos[v]++] = u;
    }

    free(edges_u);
    free(edges_v);
    free(cur_pos);

    for (int i = 1; i <= N; i++) {
        if (deg[i] > 1) {
            qsort(&adj[offset[i]], deg[i], sizeof(int), cmp_int);
        }
    }

    int total_states = 4 * M;
    int *val = (int *)malloc(total_states * sizeof(int));
    for (int i = 0; i < total_states; i++) {
        val[i] = -1;
    }

    Frame *st = (Frame *)malloc((total_states + 5) * sizeof(Frame));

    // Mapeamento inverso de aresta id -> vértice u
    int *edge_u = (int *)malloc(2 * M * sizeof(int));
    for (int i = 1; i <= N; i++) {
        for (int j = 0; j < deg[i]; j++) {
            edge_u[offset[i] + j] = i;
        }
    }

    for (int s = 1; s <= N; s++) {
        if (deg[s] == 0) continue;
        int start_node = 2 * offset[s] + 1; // S(s, 0)
        if (val[start_node] != -1) continue;

        int top = 0;
        st[top].node = start_node;
        st[top].state = 0;

        while (top >= 0) {
            int node = st[top].node;
            int state = st[top].state;

            if (node % 2 == 1) { // Nó Sufixo: S(u, i)
                int id = node / 2;
                int u = edge_u[id];
                int i = id - offset[u];

                if (state == 0) {
                    st[top].state = 1;
                    int child1 = 2 * id; // A(u, i)
                    if (val[child1] == -1) {
                        top++;
                        st[top].node = child1;
                        st[top].state = 0;
                        continue;
                    }
                }
                if (state <= 1) {
                    st[top].state = 2;
                    if (i + 1 < deg[u]) {
                        int child2 = 2 * (id + 1) + 1; // S(u, i+1)
                        if (val[child2] == -1) {
                            top++;
                            st[top].node = child2;
                            st[top].state = 0;
                            continue;
                        }
                    }
                }

                // Ambos os filhos calculados
                int child1 = 2 * id;
                int res = val[child1];
                if (i + 1 < deg[u]) {
                    int child2 = 2 * (id + 1) + 1;
                    if (val[child2] > res) {
                        res = val[child2];
                    }
                }
                val[node] = res;
                top--;
            } else { // Nó Aresta: A(u, i)
                int id = node / 2;
                int u = edge_u[id];
                int v = adj[id];

                // Busca binária pelo primeiro vizinho de v que seja > u
                int l = 0, r = deg[v] - 1;
                int idx_prime = deg[v];
                while (l <= r) {
                    int mid = l + (r - l) / 2;
                    if (adj[offset[v] + mid] > u) {
                        idx_prime = mid;
                        r = mid - 1;
                    } else {
                        l = mid + 1;
                    }
                }

                if (idx_prime < deg[v]) {
                    int child = 2 * (offset[v] + idx_prime) + 1; // S(v, idx_prime)
                    if (state == 0) {
                        st[top].state = 1;
                        if (val[child] == -1) {
                            top++;
                            st[top].node = child;
                            st[top].state = 0;
                            continue;
                        }
                    }
                    val[node] = 1 + val[child];
                } else {
                    val[node] = 1;
                }
                top--;
            }
        }
    }

    for (int i = 1; i <= N; i++) {
        int ans = 1;
        if (deg[i] > 0) {
            ans = 1 + val[2 * offset[i] + 1];
        }
        printf("%d%c", ans, (i == N ? '\n' : ' '));
    }

    free(edge_u);
    free(deg);
    free(offset);
    free(adj);
    free(val);
    free(st);

    return 0;
}
